<script setup>
import { computed,ref,watch } from 'vue'
import { Search, ChevronDown, SlidersHorizontal, X } from 'lucide-vue-next'
const props = defineProps({ filters: {type:Object,required:true}, categories: {type:Array,default:()=>[]}, colors:{type:Array,default:()=>[]}, products:{type:Array,default:()=>[]} })
const emit = defineEmits(['change','clear'])
const open = ref(false), brandSearch = ref(''), expanded = ref(['Brand']), minVal = ref(props.filters.minPrice||''), maxVal=ref(props.filters.maxPrice||'')
watch(() => [props.filters.minPrice,props.filters.maxPrice],([a,b])=>{minVal.value=a||'';maxVal.value=b||''})
const brands = computed(() => [...new Set(props.products.map(x=>x.brand))].filter(x=>x.toLowerCase().includes(brandSearch.value.toLowerCase())))
const memories = computed(() => [...new Set(props.products.map(p=>p.characteristics.find(c=>/объ[её]м.*памят/i.test(c.characteristic))?.value).filter(Boolean))].sort((a,b)=>Number(a)-Number(b)))
function toggle(section) { expanded.value = expanded.value.includes(section)?expanded.value.filter(x=>x!==section):[...expanded.value,section] }
function change(field,value) { emit('change',{[field]:value}) }
function reset() { emit('clear'); brandSearch.value=''; minVal.value='';maxVal.value='' }
</script>
<template><button type="button" class="mobile-filter-button" @click="open=!open"><SlidersHorizontal :size="18"/> Filters <X v-if="open" :size="18"/></button><aside class="filters-panel" :class="{'filters-panel--open':open}"><section class="filter-section"><button class="filter-heading" type="button" @click="toggle('Brand')"><span>Brand</span><ChevronDown :size="22" :class="{rotated:expanded.includes('Brand')}"/></button><div v-if="expanded.includes('Brand')" class="filter-section-body"><label class="filter-search"><Search :size="18"/><input v-model="brandSearch" placeholder="Search" aria-label="Search brand"/></label><label v-for="brand in brands" :key="brand" class="filter-checkbox"><input type="checkbox" :checked="filters.brand===brand" @change="change('brand',filters.brand===brand?'':brand)"/><span>{{ brand }}</span><small>{{ products.filter(x=>x.brand===brand).length }}</small></label></div></section><section v-for="section in ['Battery capacity','Screen type','Screen diagonal','Protection class','Built-in memory']" :key="section" class="filter-section"><button type="button" class="filter-heading" @click="toggle(section)"><span>{{ section }}</span><ChevronDown :size="22" :class="{rotated:expanded.includes(section)}"/></button><div v-if="expanded.includes(section)" class="filter-section-body"><template v-if="section==='Built-in memory'"><label v-for="mem in memories" :key="mem" class="filter-checkbox"><input type="checkbox" :checked="filters.memory===mem" @change="change('memory',filters.memory===mem?'':mem)"/><span>{{ mem }} GB</span></label></template><template v-else-if="section==='Battery capacity'"><label v-for="b in ['2000','3000','4000']" :key="b" class="filter-checkbox"><input type="checkbox" :checked="filters.battery===b" @change="change('battery',filters.battery===b?'':b)"/><span>{{ b }} mAh+</span></label></template><p v-else class="filter-hint">This property is not provided by the product API.</p></div></section><section class="filter-section extra-filter"><button type="button" class="filter-heading" @click="toggle('Price')"><span>Price</span><ChevronDown :size="22" :class="{rotated:expanded.includes('Price')}"/></button><form v-if="expanded.includes('Price')" class="price-fields" @submit.prevent="emit('change',{minPrice:minVal,maxPrice:maxVal})"><input v-model="minVal" type="number" min="0" placeholder="From" aria-label="Min price"/><input v-model="maxVal" type="number" min="0" placeholder="To" aria-label="Max price"/><button class="outline-button">Apply</button></form></section><button class="filter-reset" type="button" @click="reset">Reset filters</button></aside></template>
